export type OrderStatus = "pending" | "shipped" | "cancelled";
export type Order = { id: string; customerId: string; status: OrderStatus; items: string[] };

export class OrderStateError extends Error {}

/** Domain rule: only pending orders can be cancelled. Returns the new order value. */
export function cancel(order: Order): Order {
  if (order.status !== "pending") throw new OrderStateError("order " + order.id + " is " + order.status);
  return { ...order, status: "cancelled" };
}

/** Domain rule: merge source order items into target order. Both must be pending. */
export function merge(source: Order, target: Order): Order {
  if (source.status !== "pending") throw new OrderStateError("source order " + source.id + " is " + source.status);
  if (target.status !== "pending") throw new OrderStateError("target order " + target.id + " is " + target.status);
  return { ...target, items: [...target.items, ...source.items] };
}
